INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('3150871f-70f0-5aa8-98dd-42cbd1d68974', '03812cdf-a8e0-5f66-a5df-4b471b3a51ec', 'en', $h$Oil Gun Holder – 7110$h$, $h$oil-gun-holder-7110$h$, NULL, $h$<div> <div><p><strong>Why the 7110 Drip Tray?</strong></p><p>The oil gun holder is equipped with a hose hook and a drip tray. It is an auxiliary accessory used beneath hose reels. It is essential for a clean, organized workplace and occupational safety. Oil collected in the drip tray can be easily drained via the valve located underneath it. It is coated with electrostatic powder paint.</p><p> </p></div> </div>$h$, NULL, $h$Oil Gun Holder – 7110 | HD Marine$h$, $h$Why the 7110 Drip Tray? The oil gun holder is equipped with a hose hook and a drip tray. It is an auxiliary accessory used beneath hose reels. It is…$h$, 'auto') ON CONFLICT DO NOTHING;
