INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('f77c2e3c-daa3-5d83-a6fa-396989133dd9', 'c8d6774a-0be2-55ae-a2c1-a11de7ebeec4', 'en', $h$Automatic Fuel Nozzle 3/4 – 4312$h$, $h$automatic-fuel-nozzle-3-4-4312$h$, NULL, $h$<div> <div><p><strong>Why the 4312 Automatic Fuel Nozzle?</strong></p><p>You use this nozzle to transfer diesel, gasoline and fuels containing up to 10% ethanol. With its automatic fuel shut-off feature, which activates if the nozzle is dropped or lifted during filling, it prevents spills and hazardous situations. It offers you an ideal solution for applications requiring high flow rates.</p></div> </div>$h$, NULL, $h$Automatic Fuel Nozzle 3/4 – 4312 | HD Marine$h$, $h$Why the 4312 Automatic Fuel Nozzle? You use this nozzle to transfer diesel, gasoline and fuels containing up to 10% ethanol. With its automatic fuel…$h$, 'auto') ON CONFLICT DO NOTHING;
