INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('4ce55511-b4f6-5cc0-bcbe-dd4e9014bd70', 'adc48422-61c4-5e95-b0c6-d8633cecc372', 'en', $h$Digital Oil Meter – 4104$h$, $h$digital-oil-meter-4104$h$, NULL, $h$<div> <div><p><strong>Why the 4104 Digital Oil Meter?</strong></p><p>The digital oil meter features an oval gear design and is a manageable, ergonomic device for controlling and managing oil dispensing. The meter body is made of die-cast aluminum resistant to high pressures. It is easy to calibrate and has an electronic reset function. In addition to low battery consumption, it carries an IP65 protection rating.</p></div> </div>$h$, NULL, $h$Digital Oil Meter – 4104 | HD Marine$h$, $h$Why the 4104 Digital Oil Meter? The digital oil meter features an oval gear design and is a manageable, ergonomic device for controlling and managing oil…$h$, 'auto') ON CONFLICT DO NOTHING;
