INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('4536cd9e-10da-5444-a638-e5faa7f66530', '5f791864-ea9d-5f3c-84ea-64d325eac5a3', 'en', $h$Grease Follower Weight – 2620$h$, $h$grease-follower-weight-2620$h$, NULL, $h$<div> <div><p><strong>Why the 2620 Grease Follower Weight?</strong></p><p>The plate weight we designed for drum-type grease pumps facilitates the downward flow of grease. You should also use it together with the drum-type follower plate.</p></div> </div>$h$, NULL, $h$Grease Follower Weight – 2620 | HD Marine$h$, $h$Why the 2620 Grease Follower Weight? The plate weight we designed for drum-type grease pumps facilitates the downward flow of grease. You should also use…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('8596c177-5015-5a77-9fce-9de3ee25e040', '2da2d26b-cefb-5089-876b-5248eba43ace', 'en', $h$Drum Trolley – 2420$h$, $h$drum-trolley-2420$h$, NULL, $h$<div> <div><p><strong>Why the 2420 Drum Trolley?</strong></p><p>Our modular trolleys, suitable for 185 Kg or 208 Lt drums, use two fixed and three swivel casters. The ball-bearing fixed casters increase maneuverability. Its compact dimensions and portability save space and time. You can fit a hose reel of any desired type and specification onto this model. The product has an electrostatic paint coating.</p></div> </div>$h$, NULL, $h$Drum Trolley – 2420 | HD Marine$h$, $h$Why the 2420 Drum Trolley? Our modular trolleys, suitable for 185 Kg or 208 Lt drums, use two fixed and three swivel casters. The ball-bearing fixed…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('f55b56ac-d399-5d48-acea-ecef38f9c8d8', '35b86257-6774-51cb-9437-3fd3c952d5db', 'en', $h$Grease Pail Trolley – 2416$h$, $h$grease-pail-trolley-2416$h$, NULL, $h$<div> <div><p><strong>Why the 2416 Grease Pail Trolley?</strong></p><p>It allows pail-type grease pumps to be transported easily. It has two heavy-duty wheels.</p></div> </div>$h$, NULL, $h$Grease Pail Trolley – 2416 | HD Marine$h$, $h$Why the 2416 Grease Pail Trolley? It allows pail-type grease pumps to be transported easily. It has two heavy-duty wheels.$h$, 'auto') ON CONFLICT DO NOTHING;
